-- Chronic Care Loop · relational backend (PostgreSQL)
-- Generated by tools/gen_schema.js from src/hub/database.html. Sample rows come from tools/gen_model.py (a scripted demo day over the extract sample).

-- Nurses, coordinators and clinical leads, with languages and daily capacity.
CREATE TABLE care_team_user (
  user_id          TEXT NOT NULL,
  name             TEXT NOT NULL,
  role             TEXT NOT NULL,
  languages        TEXT,
  daily_capacity   INT,
  PRIMARY KEY (user_id)
);

-- One row per load of the member-level extract (167 rows × 341 columns in production; 24-row sample here).
CREATE TABLE ingest_run (
  run_id           TEXT NOT NULL,
  source_file      TEXT NOT NULL,
  as_of_date       TEXT NOT NULL,
  row_count        INT NOT NULL,
  column_count     INT NOT NULL,
  loaded_at        TEXT NOT NULL,
  PRIMARY KEY (run_id)
);

-- Each extract row exactly as received, as JSON, so nothing is lost when values are typed.
CREATE TABLE src_member_row (
  run_id           TEXT NOT NULL,
  member_id        TEXT NOT NULL,
  raw_json         TEXT NOT NULL,
  PRIMARY KEY (run_id, member_id),
  FOREIGN KEY (run_id) REFERENCES ingest_run (run_id)
);

-- What the loader found: 999 placeholders, impossible readings, score and tier mismatches.
CREATE TABLE data_issue (
  issue_id         INT NOT NULL,
  run_id           TEXT NOT NULL,
  member_id        TEXT,
  column_name      TEXT,
  raw_value        TEXT,
  rule             TEXT NOT NULL,
  severity         TEXT NOT NULL,
  PRIMARY KEY (issue_id),
  FOREIGN KEY (run_id) REFERENCES ingest_run (run_id)
);

-- Rulebook §3: each trigger, the raw columns it reads, the next best action, owner and proof of completion.
CREATE TABLE trigger_def (
  trigger_code     TEXT NOT NULL,
  name             TEXT NOT NULL,
  pathway          TEXT NOT NULL,
  raw_columns      TEXT NOT NULL,
  fires_when       TEXT NOT NULL,
  action_title     TEXT NOT NULL,
  owner_role       TEXT NOT NULL,
  done_when        TEXT NOT NULL,
  class            TEXT NOT NULL,
  sort_order       INT NOT NULL,
  PRIMARY KEY (trigger_code)
);

-- One row per masked member (mask_id). Consent is the only column the loop writes.
CREATE TABLE member (
  member_id        TEXT NOT NULL,
  gender           TEXT,
  age              INT,
  nationality      TEXT,
  plan_name        TEXT,
  policy_group     TEXT,
  policy_type      TEXT,
  gwp              NUMERIC,
  risk_premium     NUMERIC,
  language         TEXT,
  consent_status   TEXT NOT NULL,
  PRIMARY KEY (member_id)
);

-- The catalogue: one row per glossary column plus derived fields. Risk, triggers and persona are not selectable.
CREATE TABLE feature (
  feature_key      TEXT NOT NULL,
  label            TEXT NOT NULL,
  category         TEXT NOT NULL,
  description      TEXT,
  source           TEXT NOT NULL,
  value_type       TEXT NOT NULL,
  unit             TEXT,
  cohort_selectable INT NOT NULL,
  definition       TEXT,
  created_by       TEXT,
  created_at       TEXT,
  PRIMARY KEY (feature_key),
  FOREIGN KEY (created_by) REFERENCES care_team_user (user_id)
);

-- Every extract value in typed long form. Dates hold days before the as-of date, so rules stay simple.
CREATE TABLE member_feature (
  member_id        TEXT NOT NULL,
  feature_key      TEXT NOT NULL,
  value_num        NUMERIC,
  value_text       TEXT,
  as_of            TEXT NOT NULL,
  PRIMARY KEY (member_id, feature_key),
  FOREIGN KEY (member_id) REFERENCES member (member_id),
  FOREIGN KEY (feature_key) REFERENCES feature (feature_key)
);

-- A saved builder definition, versioned. row_count is refreshed each run.
CREATE TABLE cohort (
  cohort_id        TEXT NOT NULL,
  version          INT NOT NULL,
  name             TEXT NOT NULL,
  base             TEXT NOT NULL,
  logic            TEXT NOT NULL,
  refresh          TEXT NOT NULL,
  definition_type  TEXT NOT NULL,
  row_count        INT,
  owner            TEXT,
  created_at       TEXT NOT NULL,
  PRIMARY KEY (cohort_id),
  FOREIGN KEY (owner) REFERENCES care_team_user (user_id)
);

-- The builder rules as rows: field, operator, values, include or exclude.
CREATE TABLE cohort_rule (
  rule_id          TEXT NOT NULL,
  cohort_id        TEXT NOT NULL,
  version          INT NOT NULL,
  field            TEXT NOT NULL,
  operator         TEXT,
  value            TEXT,
  value2           TEXT,
  codes            TEXT,
  lab              TEXT,
  is_exclusion     INT NOT NULL,
  PRIMARY KEY (rule_id),
  FOREIGN KEY (cohort_id) REFERENCES cohort (cohort_id)
);

-- Who matched on the last run, with the stable-hash 10% holdout flag.
CREATE TABLE cohort_member (
  cohort_id        TEXT NOT NULL,
  member_id        TEXT NOT NULL,
  version          INT NOT NULL,
  holdout          INT NOT NULL,
  run_at           TEXT NOT NULL,
  PRIMARY KEY (cohort_id, member_id),
  FOREIGN KEY (cohort_id) REFERENCES cohort (cohort_id),
  FOREIGN KEY (member_id) REFERENCES member (member_id)
);

-- Goal, trigger mode, channels, capacity, start and status.
CREATE TABLE campaign (
  campaign_id      TEXT NOT NULL,
  name             TEXT NOT NULL,
  goal             TEXT,
  trigger_mode     TEXT NOT NULL,
  triggers_json    TEXT,
  channels         TEXT NOT NULL,
  nurses           INT NOT NULL,
  calls_per_day    INT NOT NULL,
  holdout_pct      INT NOT NULL,
  start_date       TEXT NOT NULL,
  weeks            INT NOT NULL,
  priority         INT NOT NULL,
  status           TEXT NOT NULL,
  created_at       TEXT NOT NULL,
  PRIMARY KEY (campaign_id)
);

-- Which cohorts a campaign includes or excludes.
CREATE TABLE campaign_cohort (
  campaign_id      TEXT NOT NULL,
  cohort_id        TEXT NOT NULL,
  role             TEXT NOT NULL,
  PRIMARY KEY (campaign_id, cohort_id),
  FOREIGN KEY (campaign_id) REFERENCES campaign (campaign_id),
  FOREIGN KEY (cohort_id) REFERENCES cohort (cohort_id)
);

-- Rulebook §2 per member per run: C+M+K+U+A, tier, alert colour, contact priority P1–P4.
CREATE TABLE assessment (
  member_id        TEXT NOT NULL,
  run_id           TEXT NOT NULL,
  clinical         INT,
  comorbid         INT,
  kidney           INT,
  utilisation      INT,
  age_sex          INT,
  kidney_provisional INT NOT NULL,
  r_total          INT NOT NULL,
  tier             INT NOT NULL,
  tier_label       TEXT NOT NULL,
  persona          TEXT,
  allocation       TEXT,
  priority_review  INT NOT NULL,
  excluded         INT NOT NULL,
  alert            TEXT NOT NULL,
  contact_priority TEXT NOT NULL,
  PRIMARY KEY (member_id, run_id),
  FOREIGN KEY (member_id) REFERENCES member (member_id),
  FOREIGN KEY (run_id) REFERENCES ingest_run (run_id)
);

-- A trigger that fired (or could not be judged) for a campaign member on this run.
CREATE TABLE signal (
  signal_id        TEXT NOT NULL,
  member_id        TEXT NOT NULL,
  campaign_id      TEXT NOT NULL,
  run_id           TEXT NOT NULL,
  trigger_code     TEXT NOT NULL,
  state            TEXT NOT NULL,
  evidence         TEXT,
  status           TEXT NOT NULL,
  PRIMARY KEY (signal_id),
  FOREIGN KEY (member_id) REFERENCES member (member_id),
  FOREIGN KEY (campaign_id) REFERENCES campaign (campaign_id),
  FOREIGN KEY (run_id) REFERENCES ingest_run (run_id),
  FOREIGN KEY (trigger_code) REFERENCES trigger_def (trigger_code)
);

-- One plan per member: pathway, tier and the cadence that follows from it.
CREATE TABLE care_plan (
  care_plan_id     TEXT NOT NULL,
  member_id        TEXT NOT NULL,
  pathway          TEXT NOT NULL,
  tier             INT NOT NULL,
  cadence          TEXT NOT NULL,
  status           TEXT NOT NULL,
  opened_at        TEXT NOT NULL,
  updated_at       TEXT NOT NULL,
  PRIMARY KEY (care_plan_id),
  FOREIGN KEY (member_id) REFERENCES member (member_id)
);

-- One need per trigger, ordered safety → goal. Top 3 are CURRENT, 4–6 NEXT, the rest FUTURE.
CREATE TABLE care_plan_need (
  need_id          TEXT NOT NULL,
  care_plan_id     TEXT NOT NULL,
  signal_id        TEXT,
  need_key         TEXT NOT NULL,
  class            TEXT NOT NULL,
  slot             TEXT NOT NULL,
  title            TEXT NOT NULL,
  owner_role       TEXT NOT NULL,
  done_when        TEXT NOT NULL,
  due_date         TEXT,
  status           TEXT NOT NULL,
  hold_until       TEXT,
  PRIMARY KEY (need_id),
  FOREIGN KEY (care_plan_id) REFERENCES care_plan (care_plan_id),
  FOREIGN KEY (signal_id) REFERENCES signal (signal_id),
  FOREIGN KEY (need_key) REFERENCES trigger_def (trigger_code)
);

-- Work for the team: one care-plan action per CURRENT need, plus worklist calls and retries.
CREATE TABLE action (
  action_id        TEXT NOT NULL,
  member_id        TEXT NOT NULL,
  need_id          TEXT,
  kind             TEXT NOT NULL,
  title            TEXT NOT NULL,
  agreed           INT NOT NULL,
  due_date         TEXT NOT NULL,
  assignee         TEXT,
  status           TEXT NOT NULL,
  closed_at        TEXT,
  source           TEXT NOT NULL,
  created_at       TEXT NOT NULL,
  PRIMARY KEY (action_id),
  FOREIGN KEY (member_id) REFERENCES member (member_id),
  FOREIGN KEY (need_id) REFERENCES care_plan_need (need_id),
  FOREIGN KEY (assignee) REFERENCES care_team_user (user_id)
);

-- A call attempt: who, when, reached or not, consent and response.
CREATE TABLE contact (
  contact_id       TEXT NOT NULL,
  member_id        TEXT NOT NULL,
  campaign_id      TEXT,
  user_id          TEXT,
  started_at       TEXT NOT NULL,
  ended_at         TEXT,
  reached          INT,
  consent          TEXT,
  response         TEXT,
  notes            TEXT,
  PRIMARY KEY (contact_id),
  FOREIGN KEY (member_id) REFERENCES member (member_id),
  FOREIGN KEY (campaign_id) REFERENCES campaign (campaign_id),
  FOREIGN KEY (user_id) REFERENCES care_team_user (user_id)
);

-- What happened to a need or action. The nightly run reads and stamps it.
CREATE TABLE outcome (
  outcome_id       TEXT NOT NULL,
  contact_id       TEXT,
  member_id        TEXT NOT NULL,
  need_id          TEXT,
  action_id        TEXT,
  result           TEXT NOT NULL,
  recorded_by      TEXT,
  recorded_at      TEXT NOT NULL,
  processed_at     TEXT,
  PRIMARY KEY (outcome_id),
  FOREIGN KEY (contact_id) REFERENCES contact (contact_id),
  FOREIGN KEY (member_id) REFERENCES member (member_id),
  FOREIGN KEY (need_id) REFERENCES care_plan_need (need_id),
  FOREIGN KEY (action_id) REFERENCES action (action_id),
  FOREIGN KEY (recorded_by) REFERENCES care_team_user (user_id)
);

-- Every read and write the API makes: the data lens behind both screens.
CREATE TABLE event_log (
  event_id         INT NOT NULL,
  at               TEXT NOT NULL,
  actor            TEXT,
  endpoint         TEXT,
  op               TEXT NOT NULL,
  table_name       TEXT NOT NULL,
  detail           TEXT,
  PRIMARY KEY (event_id)
);

-- One care-plan need has at most one care-plan action
CREATE UNIQUE INDEX action_one_per_need ON action (need_id) WHERE kind = 'care_plan';
-- Nightly run picks up unprocessed outcomes
CREATE INDEX outcome_unprocessed ON outcome (recorded_at) WHERE processed_at IS NULL;

